const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const https = require('https');
const { URL } = require('url');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');
const memoryPath = path.join(userDataDir, 'memory_rules.json');

const rawOutput = String($input.first()?.json?.output || '').trim();
const nowIso = new Date().toISOString();
const today = nowIso.slice(0, 10);

// 1. Safely strip accidental Markdown code fences & parse JSON
const cleanedJsonStr = rawOutput
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let briefingText = rawOutput;
let tasksToCreate = [];
let trackerMutations = [];

try {
  const parsed = JSON.parse(cleanedJsonStr);
  if (parsed && typeof parsed === 'object') {
    if (typeof parsed.briefing_text === 'string' && parsed.briefing_text.trim()) {
      briefingText = parsed.briefing_text.trim();
    }
    if (Array.isArray(parsed.tasks_to_create)) {
      tasksToCreate = parsed.tasks_to_create
        .filter((t) => t && typeof t.title === 'string' && t.title.trim().length > 0)
        .map((t) => ({
          title: t.title.trim(),
          notes: typeof t.notes === 'string' ? t.notes.trim() : '',
          due_date: typeof t.due_date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(t.due_date.trim())
            ? t.due_date.trim()
            : null
        }));
    }
    if (Array.isArray(parsed.tracker_mutations)) {
      trackerMutations = parsed.tracker_mutations.filter(
        (m) => m && typeof m.tracker_id === 'string' && m.tracker_id.trim().length > 0
      );
    }
  }
} catch (err) {
  briefingText = cleanedJsonStr || rawOutput;
  tasksToCreate = [];
  trackerMutations = [];
}

// 2. Execute tracker_mutations safely with idempotency safeguard
const mutationsApplied = [];
if (trackerMutations.length > 0 && fs.existsSync(registryPath)) {
  const registry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
  let registryModified = false;

  for (const mutation of trackerMutations) {
    const trackerId = String(mutation.tracker_id || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '_');
    const tracker = registry.trackers?.[trackerId];
    if (!tracker) continue;

    const op = mutation.operation || 'advance_cycle';
    const dataFilePath = path.join(userDataDir, `data_${trackerId}.json`);
    const records = fs.existsSync(dataFilePath)
      ? JSON.parse(fs.readFileSync(dataFilePath, 'utf8'))
      : [];

    if (['advance_cycle', 'skip_or_shift_cycle', 'set_cycle_index'].includes(op)) {
      if (!tracker.cycle_config || !Array.isArray(tracker.cycle_config.steps) || tracker.cycle_config.steps.length === 0) {
        continue;
      }
      const steps = tracker.cycle_config.steps;
      const prevIndex = Number(tracker.cycle_config.current_index || 0);
      const defaultDelta = op === 'skip_or_shift_cycle' ? 0 : 1;
      const delta = typeof mutation.step_delta === 'number' ? mutation.step_delta : defaultDelta;

      // Idempotency Safeguard: Never double-advance a cycle on the same day
      if (op === 'advance_cycle' && delta !== 0 && tracker.cycle_config.last_updated === today) {
        continue;
      }

      let nextIndex = prevIndex;
      if (op === 'set_cycle_index' && typeof mutation.target_index === 'number') {
        nextIndex = ((mutation.target_index % steps.length) + steps.length) % steps.length;
      } else {
        nextIndex = ((prevIndex + delta) % steps.length + steps.length) % steps.length;
      }

      tracker.cycle_config.current_index = nextIndex;
      tracker.cycle_config.last_updated = today;
      registry.trackers[trackerId] = tracker;
      registryModified = true;

      const logEntry = {
        id: crypto.randomUUID(),
        event: op,
        source: 'morning_briefing',
        previous_step: steps[prevIndex],
        current_step: steps[nextIndex],
        ...(mutation.record_data && typeof mutation.record_data === 'object' ? mutation.record_data : {}),
        created_at: nowIso,
        updated_at: nowIso
      };
      records.push(logEntry);
      fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');

      mutationsApplied.push({
        tracker_id: trackerId,
        operation: op,
        previous_step: steps[prevIndex],
        current_index: nextIndex,
        current_step: steps[nextIndex]
      });
    } else if (op === 'update' && mutation.record_id) {
      const idx = records.findIndex((r) => r.id === mutation.record_id);
      if (idx !== -1) {
        records[idx] = {
          ...records[idx],
          ...(mutation.record_data && typeof mutation.record_data === 'object' ? mutation.record_data : {}),
          id: records[idx].id,
          created_at: records[idx].created_at,
          updated_at: nowIso
        };
        fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');
        mutationsApplied.push({
          tracker_id: trackerId,
          operation: 'update',
          record_id: mutation.record_id
        });
      }
    } else if (op === 'insert') {
      const newRecord = {
        id: crypto.randomUUID(),
        ...(mutation.record_data && typeof mutation.record_data === 'object' ? mutation.record_data : {}),
        created_at: nowIso,
        updated_at: nowIso
      };
      records.push(newRecord);
      fs.writeFileSync(dataFilePath, JSON.stringify(records, null, 2), 'utf8');
      mutationsApplied.push({
        tracker_id: trackerId,
        operation: 'insert',
        record_id: newRecord.id
      });
    }
  }

  if (registryModified) {
    fs.writeFileSync(registryPath, JSON.stringify(registry, null, 2), 'utf8');
  }
}

// 3. Save today's briefing state in memory_rules.json under custom_scopes.today_briefing_state
const memory = fs.existsSync(memoryPath)
  ? JSON.parse(fs.readFileSync(memoryPath, 'utf8'))
  : { morning_rules: [], custom_scopes: {} };

if (!memory.custom_scopes || typeof memory.custom_scopes !== 'object') {
  memory.custom_scopes = {};
}

memory.custom_scopes.today_briefing_state = [
  {
    id: crypto.randomUUID(),
    instruction: `Briefing matinal proposé le ${today} : ${briefingText}`,
    volatile: true,
    expires_at: today,
    created_at: nowIso
  }
];

fs.writeFileSync(memoryPath, JSON.stringify(memory, null, 2), 'utf8');

// 4. Dispatch to Discord via DISCORD_BRIEFING_WEBHOOK_URL if configured
const webhookUrl = (typeof $env !== 'undefined' && $env.DISCORD_BRIEFING_WEBHOOK_URL ? $env.DISCORD_BRIEFING_WEBHOOK_URL : '').trim();
let discordSent = false;
let discordWarning = null;

function postDiscordWebhook(targetUrl, payloadObj) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(targetUrl);
    const bodyStr = JSON.stringify(payloadObj);
    const req = https.request(
      {
        hostname: parsed.hostname,
        port: parsed.port || 443,
        path: parsed.pathname + parsed.search,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(bodyStr)
        }
      },
      (res) => {
        let resBody = '';
        res.on('data', (chunk) => { resBody += chunk; });
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve(true);
          } else {
            reject(new Error(`Discord HTTP ${res.statusCode}: ${resBody}`));
          }
        });
      }
    );
    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

if (webhookUrl && webhookUrl.startsWith('http') && !webhookUrl.includes('/xxx/yyy')) {
  try {
    await postDiscordWebhook(webhookUrl, {
      username: 'Jarvis Morning Briefing',
      content: briefingText
    });
    discordSent = true;
  } catch (err) {
    discordWarning = err.message;
  }
} else {
  discordWarning = 'DISCORD_BRIEFING_WEBHOOK_URL is empty or placeholder; skipped Discord HTTP dispatch.';
}

return [
  {
    json: {
      status: 'ok',
      discord_sent: discordSent,
      ...(discordWarning ? { warning: discordWarning } : {}),
      tasks_to_create: tasksToCreate,
      tasks_created_count: tasksToCreate.length,
      mutations_applied_count: mutationsApplied.length,
      mutations_applied: mutationsApplied,
      briefing: briefingText,
      timestamp: nowIso
    }
  }
];

const tasks = Array.isArray($input.first()?.json?.tasks_to_create)
  ? $input.first().json.tasks_to_create
  : [];

return tasks.map((t) => ({
  json: {
    title: t.title,
    notes: t.notes || '',
    due_rfc3339: t.due_date ? `${t.due_date}T09:00:00.000Z` : undefined
  }
}));

const parsedState = $('Parse Briefing & Tasks').first().json;

return [
  {
    json: {
      status: 'ok',
      discord_sent: parsedState.discord_sent,
      ...(parsedState.warning ? { warning: parsedState.warning } : {}),
      tasks_created_count: parsedState.tasks_created_count || 0,
      tasks_to_create: parsedState.tasks_to_create || [],
      mutations_applied_count: parsedState.mutations_applied_count || 0,
      mutations_applied: parsedState.mutations_applied || [],
      briefing: parsedState.briefing,
      timestamp: parsedState.timestamp
    }
  }
];
